Here are the steps to create a unit test that uses data sources defined in an app.config file:

    1. Add a unit test to the test project.

    2. Replace the auto-generated contents of the unit test with the appropriate code, making sure to set up the necessary data sources and specifying the correct deployment items and DataSource attributes.

    3. After writing the code, examine the DataSource attributes to ensure they match the setting names from the app.config file.

    4. Finally, build your solution and run the tests.

    For example, here is some code that could be used to create a unit test:

    ```csharp
    using System;
    using Microsoft.VisualStudio.TestTools.UnitTesting;

    namespace TestProject1
    {
         [TestClass]
        public class UnitTest1
        {
            private TestContext context;

            public TestContext TestContext
            {
                get { return context; }
                set { context = value; }
            }

            [TestMethod()]
            [DeploymentItem("MyTestProject\\testdatasource.accdb")]
            [DataSource("MyJetDataSource")]
            public void MyTestMethod()
            {
                int a = Int32.Parse(context.DataRow["Arg1"].ToString());
                int b = Int32.Parse(context.DataRow["Arg2"].ToString());
                Assert.AreNotEqual(a, b, "A value was equal.");
            }

            [TestMethod()]
            [DeploymentItem("MyTestProject\\data.xlsx")]
            [DataSource("MyExcelDataSource")]
            public void MyTestMethod2()
            {
                Assert.AreEqual(context.DataRow["Val1"], context.DataRow["Val2"]);
            }
        }
    }
    ```
